    extrude(context, id + "cyl", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 30 * millimeter, "oppositeDirection" : false });
    opPoint(context, id + "help", { "point" : vector(0, 14, 0) * millimeter });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : false, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "cyl", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 2 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : true, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "helpPoint" : qCreatedBy(id + "help", EntityType.VERTEX) });
